using TdLib.TdApi;
using TdLib.TdApi.Objects;
namespace TdLib.Api.OpenTelemetry;
/// <summary>
/// Autogenerated TDLib APIs
/// </summary>

public partial class ClientOpenTelemetryDecorator
{
    /// <summary>
    /// Returns the text shown in the chat with a bot if the chat is empty in the given language. Can be called only if userTypeBot.can_be_edited == true
    /// </summary>
    public Task<TdLib.TdApi.Objects.Text> GetBotInfoDescriptionAsync(long botUserId = default, string languageCode = default)
    {

           using var activity =  StartCallActivity("GetBotInfoDescriptionAsync", typeof(GetBotInfoDescription).FullName ?? "GetBotInfoDescriptionAsync");

           try
           {
             return client.GetBotInfoDescriptionAsync(botUserId, languageCode);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
}
